WITH payments_by_order AS (SELECT order_id, MAX(amount) AS max_amount, SUM(CASE WHEN status = 'FAILED' THEN 1 ELSE 0 END) AS failed_count FROM payments WHERE method IN ('promptpay', 'cash', 'paypal') GROUP BY order_id) SELECT o.id, o.customer_id, o.discount, pbo.max_amount, pbo.failed_count FROM orders o LEFT OUTER JOIN payments_by_order pbo ON o.id = pbo.order_id WHERE pbo.failed_count >= 52 ORDER BY pbo.failed_count
